import { useState } from 'react'
import { Container, Row, Col } from 'react-bootstrap'
import Space from '../../assets/images/space1.webg'
import Philosophy from '../../assets/images/space2.jpg'
import People from '../../assets/images/space3.jpg'

const stories = [
  {
    title: 'Our Space',
    text: 'A warm place made for slowing down. Wood, fire, and the smell of fresh pizza.',
    img: Space
  },
  {
    title: 'Our Philosophy',
    text: 'We cook with respect for seasons, ingredients, and Italian tradition.',
    img: Philosophy
  },
  {
    title: 'Our People',
    text: 'Chefs, bakers, and hosts who cook with heart, not shortcuts.',
    img: People
  }
]

const RestaurantStory = () => {
  const [index, setIndex] = useState(0)
  const story = stories[index]

  return (
    <section className="restaurant_space">
      <Container>
        <Row className="align-items-center">
          <Col md={6}>
            <img src={story.img} alt={story.title} className="img-fluid" />
          </Col>

          <Col md={6}>
            <h3>{story.title}</h3>
            <p>{story.text}</p>

            <div className="story_nav">
              {stories.map((_, i) => (
                <button
                  key={i}
                  className={i === index ? 'active' : ''}
                  onClick={() => setIndex(i)}
                >
                  {i + 1}
                </button>
              ))}
            </div>
          </Col>
        </Row>
      </Container>
    </section>
  )
}

export default RestaurantStory
